import { Text } from "@chakra-ui/react";
import type { ConversationEvent } from "../../types";
import { DetailView, InfoField } from "./blocks";
import { type RawToolEvent, ToolRunEventBody } from "./ToolRunEventBody";

interface ToolExecutedEventInfoProps {
  event: ConversationEvent;
  onClose: () => void;
}

export const ToolExecutedEventInfo = ({ event, onClose }: ToolExecutedEventInfoProps) => {
  const rawEvent = event.metadata?.rawEvent as RawToolEvent | undefined;
  const source = event.metadata?.tool_source ?? rawEvent?.source;

  return (
    <DetailView title="Tool executed" onClose={onClose}>
      <ToolRunEventBody
        event={event}
        resourceLabel="Skill"
        extraFields={
          <InfoField label="Source">
            <Text textStyle="sm" data-testid="event-tool-source">
              {source ?? "—"}
            </Text>
          </InfoField>
        }
      />
    </DetailView>
  );
};
